/*
 * ESP32-S3: джойстик -> Wi-Fi -> TCP -> ПК (управление мышкой)
 * Сервер на ПК: Java, порт 8080, IP 192.168.0.152
 *
 * Распиновка: VRX=GPIO4, VRY=GPIO5, SW=GPIO10.
 */
#include <WiFi.h>

const char* WIFI_SSID = "DIR-615T-0DBC";
const char* WIFI_PASS = "23233010";
const char* PC_IP     = "192.168.0.152";
const uint16_t PC_PORT = 8080;

#define PIN_VRX 4
#define PIN_VRY 5
#define PIN_SW  10   // кнопка джойстика на GND, INPUT_PULLUP

const int CENTER = 2048;   // центр ADC при 3.3V (12 бит)
const int DEADZONE = 300;  // мёртвая зона вокруг центра, чтобы курсор не полз
const float SPEED = 25.0;  // множитель скорости: больше = быстрее

WiFiClient client;

void connectWiFi() {
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  Serial.print("Wi-Fi");
  while (WiFi.status() != WL_CONNECTED) {
    delay(400);
    Serial.print(".");
  }
  Serial.println(" ok, IP: " + WiFi.localIP().toString());
}

void connectServer() {
  Serial.print("TCP");
  while (!client.connected()) {
    if (!client.connect(PC_IP, PC_PORT)) {
      Serial.print(".");
      delay(1500);
    }
  }
  Serial.println(" connected");
}

void setup() {
  Serial.begin(115200);
  analogReadResolution(12);
  pinMode(PIN_SW, INPUT_PULLUP);

  connectWiFi();
  connectServer();
  Serial.println("Ready.");
}

void loop() {
  if (WiFi.status() != WL_CONNECTED) { connectWiFi(); return; }
  if (!client.connected())           { connectServer(); return; }

  int rawX = analogRead(PIN_VRX);
  int rawY = analogRead(PIN_VRY);

  int dx = rawX - CENTER;
  int dy = rawY - CENTER;

  // мёртвая зона + масштабирование
  if (abs(dx) < DEADZONE) dx = 0; else dx = (int)((dx - (dx > 0 ? DEADZONE : -DEADZONE)) * SPEED / (CENTER - DEADZONE));
  if (abs(dy) < DEADZONE) dy = 0; else dy = (int)((dy - (dy > 0 ? DEADZONE : -DEADZONE)) * SPEED / (CENTER - DEADZONE));

  bool btn = (digitalRead(PIN_SW) == LOW);

  // шлём строку всегда, чтобы ПК знал, что кнопка отпущена
  String msg = String(dx) + "," + String(dy) + "," + (btn ? "1" : "0") + "\n";
  client.print(msg);

  // кнопка шлётся отдельными строками, пока зажата — ПК сделает клик один раз
  if (btn) {
    while (digitalRead(PIN_SW) == LOW) {
      client.print("click\n");
      delay(50);
    }
  }

  delay(20);   // 50 Гц — достаточно плавно для курсора
}
